package com.zerostreams.app;
import android.content.Intent;import android.view.*;import android.webkit.WebView;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.lifecycle.Lifecycle;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class) public class PlayerBackTest {
 WebView find(View v){if(v instanceof WebView)return(WebView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){WebView result=find(((ViewGroup)v).getChildAt(i));if(result!=null)return result;}return null;}
 String js(ActivityScenario<SportsPlayerActivity> scenario,String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> result=new AtomicReference<>();scenario.onActivity(a->find(a.getWindow().getDecorView()).evaluateJavascript(code,r->{result.set(r);latch.countDown();}));Assert.assertTrue(latch.await(5,TimeUnit.SECONDS));return result.get();}
 @Test public void submenuBackRetainsPlayerThenFirstBackWithoutMenuExits()throws Exception{String html="<video id='movie'></video><div role='menu' id='menu' style='width:300px;height:180px'><button aria-label='Close' onclick=\"document.getElementById('menu').hidden=true\">Close</button><button>1080p</button><button>Subtitles</button></div>";Intent intent=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),SportsPlayerActivity.class).putExtra("sources",new JSONArray().put(new JSONObject().put("source_tag","Fixture").put("iframe",html)).toString()).putExtra("base","https://fixture.invalid/");try(ActivityScenario<SportsPlayerActivity> scenario=ActivityScenario.launch(intent)){for(int i=0;i<80;i++){if("\"function\"".equals(js(scenario,"typeof window.__zeroBackRequest")))break;Thread.sleep(100);}Assert.assertEquals("\"function\"",js(scenario,"typeof window.__zeroBackRequest"));scenario.onActivity(a->a.onBackPressed());Thread.sleep(600);Assert.assertEquals(Lifecycle.State.RESUMED,scenario.getState());Assert.assertEquals("true",js(scenario,"document.getElementById('menu').hidden"));Assert.assertEquals("true",js(scenario,"!!document.getElementById('movie')"));scenario.onActivity(a->a.onBackPressed());for(int i=0;i<60&&scenario.getState()!=Lifecycle.State.DESTROYED;i++)Thread.sleep(100);Assert.assertEquals(Lifecycle.State.DESTROYED,scenario.getState());}}
}
